package graphicsgo

import (
	"crypto/sha256"
	"encoding/hex"
	"image"
	"image/color"
	"testing"
)

// Pinned fixture generated by Pillow 12.3.0 with an independent Python oracle.
// The fixtures are synthetic: no game assets and no private fonts.
func digest(p []byte) string { s := sha256.Sum256(p); return hex.EncodeToString(s[:]) }
func makeMask() *image.Alpha {
	m := image.NewAlpha(image.Rect(0, 0, 33, 21))
	for y := 0; y < 21; y++ {
		for x := 0; x < 33; x++ {
			v := (x*17 + y*43 + (x*y)%13) % 256
			if (x+y)%11 == 0 {
				v = 0
			}
			if (x*3+y)%17 == 0 {
				v = 255
			}
			m.Pix[y*m.Stride+x] = uint8(v)
		}
	}
	return m
}
func TestSyntheticPillowR32C3PaintOracle(t *testing.T) {
	mask := makeMask()
	ink, err := TintMask(mask, color.NRGBA{9, 4, 9, 230})
	if err != nil {
		t.Fatal(err)
	}
	grad, err := GradientMask(mask, color.NRGBA{255, 253, 255, 255}, color.NRGBA{244, 120, 192, 180})
	if err != nil {
		t.Fatal(err)
	}
	if got := digest(ink.Pix); got != "979cdb55041ee5da61c5645c2c90f19687de4a17bf8c69841a29a350165e24a6" {
		t.Fatalf("Pillow tint drift: %s", got)
	}
	if got := digest(grad.Pix); got != "1792c61ea03a09a35efee1b24d7ba422c7ba6ad3fd95ecac5983833f8e16ce00" {
		t.Fatalf("Pillow gradient drift: %s", got)
	}
	bg := image.NewNRGBA(image.Rect(0, 0, 33, 21))
	for y := 0; y < 21; y++ {
		for x := 0; x < 33; x++ {
			i := y*bg.Stride + x*4
			bg.Pix[i] = uint8((x*11 + y*3) % 256)
			bg.Pix[i+1] = uint8((x*13 + y*19) % 256)
			bg.Pix[i+2] = uint8((x*7 + y*5) % 256)
			bg.Pix[i+3] = uint8((x*29 + y*23) % 256)
		}
	}
	if err := CompositeOver(bg, ink, image.Pt(0, 0)); err != nil {
		t.Fatal(err)
	}
	if err := CompositeOver(bg, grad, image.Pt(0, 0)); err != nil {
		t.Fatal(err)
	}
	if err := CompositeOver(bg, ink, image.Pt(-4, 3)); err != nil {
		t.Fatal(err)
	}
	if got := digest(bg.Pix); got != "7570e9f563e4e540af7d614c083e4427ef0161e6b0c4a0641e96ab581df0b3f8" {
		t.Fatalf("Pillow composite drift: %s", got)
	}
	points := map[image.Point]color.NRGBA{image.Pt(0, 0): {255, 253, 255, 255}, image.Pt(2, 5): {16, 30, 16, 231}, image.Pt(16, 10): {98, 71, 87, 251}, image.Pt(32, 20): {140, 60, 101, 202}, image.Pt(24, 6): {107, 94, 107, 230}}
	for p, want := range points {
		i := p.Y*bg.Stride + p.X*4
		got := color.NRGBA{bg.Pix[i], bg.Pix[i+1], bg.Pix[i+2], bg.Pix[i+3]}
		if got != want {
			t.Fatalf("pixel %v got=%v want=%v", p, got, want)
		}
	}
}
func TestPaintNoMutationOnBadInputAndTransparentEdge(t *testing.T) {
	if _, err := TintMask(nil, color.NRGBA{}); err == nil {
		t.Fatal("nil alpha accepted")
	}
	if _, err := GradientMask(&image.Alpha{Pix: []byte{2}, Stride: 3, Rect: image.Rect(0, 0, 4, 2)}, color.NRGBA{}, color.NRGBA{}); err == nil {
		t.Fatal("short mask accepted")
	}
	dst := image.NewNRGBA(image.Rect(7, 8, 9, 10))
	for i := range dst.Pix {
		dst.Pix[i] = 77
	}
	original := append([]byte{}, dst.Pix...)
	if err := CompositeOver(dst, &image.NRGBA{Pix: []byte{2}, Stride: 4, Rect: image.Rect(0, 0, 2, 2)}, image.Pt(7, 8)); err == nil {
		t.Fatal("short layer accepted")
	}
	for i, v := range original {
		if dst.Pix[i] != v {
			t.Fatal("partially modified on invalid layer")
		}
	}
	src := image.NewNRGBA(image.Rect(0, 0, 1, 1))
	src.Pix = []byte{255, 10, 30, 0}
	if err := CompositeOver(dst, src, image.Pt(7, 8)); err != nil {
		t.Fatal(err)
	}
	for i, v := range original {
		if dst.Pix[i] != v {
			t.Fatal("source transparent alpha mutated target")
		}
	}
	if got := OverPixels(color.NRGBA{4, 5, 6, 0}, color.NRGBA{8, 9, 10, 0}); got != (color.NRGBA{4, 5, 6, 0}) {
		t.Fatalf("transparent RGB lost: %v", got)
	}
}
